import asyncio
from subject import ServiceConsumerLagObserver

class _FakeAdmin:
    def __init__(self, committed_offsets, end_offsets):
        self._committed = committed_offsets
        self._end = end_offsets

    async def list_consumer_group_offsets(self, group_id):
        return self._committed.get(group_id, {})

    async def list_offsets(self, request):
        result = {}
        for tp in request:
            result[tp] = self._end.get(tp)
        return result

class _TP:
    def __init__(self, topic, partition):
        self.topic = topic
        self.partition = partition

    def __hash__(self):
        return hash((self.topic, self.partition))

    def __eq__(self, other):
        return isinstance(other, _TP) and self.topic == other.topic and self.partition == other.partition

    def __repr__(self):
        return f"TP({self.topic}, {self.partition})"

def test_observe_normal_case():
    tp1 = _TP("topicA", 0)
    tp2 = _TP("topicA", 1)
    tp3 = _TP("topicB", 0)

    committed = {
        "group1": {
            tp1: 100,
            tp2: 200,
            tp3: 300,
        }
    }
    end_offsets = {
        tp1: 150,
        tp2: 250,
        tp3: 350,
    }

    admin = _FakeAdmin(committed, end_offsets)
    observer = ServiceConsumerLagObserver(admin)

    async def run():
        return await observer.observe("group1")

    lag = asyncio.run(run())

    assert lag.group_id == "group1"
    assert len(lag.partition_offsets) == 3
    # Check sorting: (topicA,0), (topicA,1), (topicB,0)
    po = lag.partition_offsets
    assert po[0].topic == "topicA" and po[0].partition == 0
    assert po[0].committed_offset == 100
    assert po[0].log_end_offset == 150
    assert po[1].topic == "topicA" and po[1].partition == 1
    assert po[1].committed_offset == 200
    assert po[1].log_end_offset == 250
    assert po[2].topic == "topicB" and po[2].partition == 0
    assert po[2].committed_offset == 300
    assert po[2].log_end_offset == 350

def test_observe_empty_committed_offsets():
    admin = _FakeAdmin({}, {})
    observer = ServiceConsumerLagObserver(admin)

    async def run():
        return await observer.observe("group1")

    lag = asyncio.run(run())
    assert lag.group_id == "group1"
    assert lag.partition_offsets == ()

def test_observe_missing_log_end_offset_raises():
